WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY ends_on DESC, id) AS rn FROM promotions QUALIFY rn = 1) SELECT channel, DATE_TRUNC('YEAR', starts_on) AS year_start, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, AVG(discount_pct) FILTER (WHERE promo_code = 'SPRING10') AS spring10_avg_discount_pct, COUNT(DISTINCT promo_code) AS distinct_promo_codes, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, COUNT_IF(channel = 'mobile') AS mobile_events, COUNT_IF(promo_code = 'BUNDLE') AS bundle_events, GROUPING_ID() AS grouping_id FROM ranked GROUP BY GROUPING SETS ((channel, DATE_TRUNC('YEAR', starts_on)), (channel), ()) ORDER BY spring10_avg_discount_pct;
